output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts must not be taken into single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file",
    "text": "An agent may not push a cart from a wide aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "Whenever an agent parks a cart at the mouth of a single-file aisle, they must retrieve a cart before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileCartMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileCartMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtSingleFileMouth": {
          "pre": {
            "and": [
              "singleFileCartMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtSingleFileMouth",
      "discharge": "retrieveCartAtSingleFileMouth"
    }
  },
  {
    "id": "recover_cart_after_single_file_item",
    "text": "After interacting with an item inside a single-file shelf aisle, the agent must return to having a cart before exit.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "singleFileShelfInteraction": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "singleFileShelfInteraction",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_cartless_wandering",
    "text": "Except for the entrance cart pickup area, the designated single-file aisle mouths, and the single-file aisles themselves, agents should not move around without a cart.",
    "abstraction": {
      "state_properties": {
        "entranceCartApproach": "at(0,7)",
        "singleFileCartMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartlessMovementException": {
          "or": [
            "entranceCartApproach",
            "singleFileCartMouth",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessMovementException"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Interactions with shelves from open or wide aisles must be done while holding a cart; only single-file shelf aisles are exempt.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "openShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfFace",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "must_get_cart_at_entrance",
    "text": "At the beginning of a shopping trip, the agent is obliged to obtain a cart before exiting.",
    "abstraction": {
      "state_properties": {
        "entranceCartBay": "at(1,7)"
      },
      "events": {
        "takeEntranceCart": {
          "pre": {
            "and": [
              "entranceCartBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "drop_cart_only_at_single_file_mouths",
    "text": "Agents may set down a cart only at designated wide-aisle mouths leading into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileCartMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "singleFileCartMouth"
          }
        ]
      }
    }
  }
]
